const r=await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd,numpy as np
from scipy.stats import chi2
D=pd.read_csv('/app/dataset/synthetic_stroke_data.csv'); noise=(~D.age.between(0,120))|(~D.bmi.between(10,60))|(~D.avg_glucose_level.between(20,800));d=D.loc[~noise]
cat=((D.age<=14)&(D.smoking_status.isin(['smokes','formerly smoked'])|D.ever_married|~D.work_type.isin(['children','student'])))|((D.age<=3)&(D.work_type=='student'))
for mode in ['log','raw','remove']:
 x=d.copy()
 if mode=='log':x['avg_glucose_level']=np.log2(x.avg_glucose_level)
 if mode=='remove':
  g=x.avg_glucose_level; q1,q3=g.quantile([.25,.75]);x=x[(g>=q1-3*(q3-q1))&(g<=q3+3*(q3-q1))]
 arr=x[['age','bmi','avg_glucose_level']].div(x[['age','bmi','avg_glucose_level']].max());arr['risk_proxy']=arr.prod(axis=1)
 mu=arr.mean().to_numpy();inv=np.linalg.inv(arr.cov().to_numpy());a=arr.to_numpy()-mu;dist=np.einsum('ij,jk,ik->i',a,inv,a);mdi=set(x.index[dist>chi2.ppf(.99,4)]);s=set(D.index[noise])|mdi|set(D.index[cat])
 if mode=='remove':s|=set(d.index)-set(x.index)
 print(mode,'count',len(s),'MD',len(mdi),'overlap noise',len(mdi&set(D.index[noise])),'cat extras',len(set(D.index[cat])-set(D.index[noise])-mdi),'sorted first40',sorted(s)[:40]);
PY",workdir:"/app",max_output_tokens:1200});text(r.output);

